result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "b32.py", "content": """"RFC 4648 base32 implemented from scratch (no base64 module).

Alphabet: A-Z, 2-7. Padding: '=' so output length is a multiple of 8.
Decoding is case-insensitive and strict about padding shape and leftover bits.
"""


class B32Error(ValueError):
    """Raised on bad characters, bad padding shape, or nonzero leftover bits."""


_ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567"
_CHAR_TO_VAL = {c: i for i, c in enumerate(_ALPHABET)}
# Valid unpadded payload lengths mod 8 -> required '=' padding count.
_PAD_FOR_LEN = {0: 0, 2: 6, 4: 4, 5: 3, 7: 1}


def encode(data: bytes) -> str:
    """Encode bytes to base32 text per RFC 4648."""
    if isinstance(data, (bytearray, memoryview)):
        data = bytes(data)
    elif not isinstance(data, bytes):
        raise TypeError("encode() expects bytes-like input")

    out = []
    for i in range(0, len(data), 5):
        chunk = data[i:i + 5]
        # Accumulate chunk into a big integer, MSB first.
        acc = int.from_bytes(chunk.ljust(5, b"\x00"), "big")
        chars = []
        for shift in range(35, -1, -5):
            chars.append(_ALPHABET[(acc >> shift) & 0x1F])
        nchars = (len(chunk) * 8 + 4) // 5
        out.append("".join(chars[:nchars]) + "=" * (8 - nchars))
    return "".join(out)


def _validate_shape(text: str) -> tuple[str, int]:
    """Return (payload_chars, npad) after checking padding shape."""
    npad = len(text) - len(text.rstrip("="))
    body = text[:len(text) - npad]

    if "=" in body:
        raise B32Error("padding character before end of input")
    rem = len(text) % 8
    expected_pad = _PAD_FOR_LEN.get(rem)
    if expected_pad is None:
        raise B32Error(
            "invalid base32 length %d (mod 8); cannot be padded correctly"
            % len(text)
        )
    if npad != expected_pad:
        raise B32Error(
            "incorrect padding: got %d '=' but need %d" % (npad, expected_pad)
        )
    return body, npad


def decode(text: str) -> bytes:
    """Decode base32 text (case-insensitive) to bytes per RFC 4648."""
    if isinstance(text, (bytes, bytearray)):
        text = text.decode("ascii")
    elif not isinstance(text, str):
        raise TypeError("decode() expects str or bytes")

    body, _ = _validate_shape(text)

    acc = 0
    nbits = 0
    out = bytearray()
    for ch in body:
        val = _CHAR_TO_VAL.get(ch.upper())  # case-insensitive lookup
        if val is None:
            raise B32Error("invalid base32 character: %r" % ch)
        acc = (acc << 5) | val
        nbits += 5
        if nbits >= 8:
            nbits -= 8
            out.append((acc >> nbits) & 0xFF)
            acc &= (1 << nbits) - 1

    # Leftover bits (always < 5 here given valid padding shape) must be zero.
    if acc != 0:
        raise B32Error("nonzero padding bits in final base32 character")
    return bytes(out)
